const cardHeaderRef = useRef<HTMLDivElement>(null);

const relativeRowOffset =
  (paginate && !noPaginatedIdx ? (paginationState.page - 1) * paginationState.pageSize : 0) + countFrom;

const enableDraggableRows = _draggableRows && onReorder && rows.length > 1;
const { getRowReorderProps, draggingIndex, dropTarget, ghostRef, dragRowProps } = useTableRowDrag({
  onReorder,
  disabled: !enableDraggableRows,
});
const isDraggingReorder = isNumber(draggingIndex);

const { eventHandlers, isDragging, isOverflowing, isDragScrollEnabled } = useDragScroll<HTMLDivElement>({
  // disabled: true,
  disabled: disableDrag || isDraggingReorder,
  // modifierKey: "Shift",
});

const rowClassName = (rIdx: number) => [
  _rowClassName,
  dragRowProps.getDragRowClassName(rIdx, draggingIndex, dropTarget),
];
const blurClassName = "bg-white bg-opacity-90 backdrop-blur-sm";
return (
  <>
    {/* TODO: Card Header */}
    {/* @deprecated - move to inner header */}
    {!innerHeader &&
      renderNode(
        toolbar || searchFn ? (
          <div className={twMerge("row justify-between items-center mb-2 w-full", toolbarClassName)}>
            {renderNode(title, [titleClassName ?? "card-h3"], "div")}
            <div className="grow" />
            {searchAfterToolbar && toolbar}
            {searchFn && (
              <SearchInputV2
                size="sm"
                searchSuggestions={searchSuggestions}
                labelClassName="min-h-fit h-10"
                className="h-fit"
                key={tableKey + "-search-input"}
                {...searchPropsForInput}
                search={search}
                setSearch={setSearch}
              />
            )}
            {!searchAfterToolbar && toolbar}
          </div>
        ) : (
          title
        ),
        ["my-2", titleClassName ?? "card-h3"],
        "div"
      )}
    <div
      className={twMerge(
        "bg-white overflow-auto shadow-none rounded-2xl relative",
        " !px-0 !py-0",
        !noGrow && "min-h-max flex-grow",
        "transition outline-1 outline-neutral/0 outline-double",
        pageHeight && [
          pageHeight === true && "max-h-[calc(100vh-100px)]",
          typeof pageHeight === "string" && pageHeight,
        ],
        !disableDrag && isOverflowing && isDragging && "outline-neutral/25 outline-dashed !shadow-sm drag-select",
        // card && "card",
        // cardCompact && "card card-compact",
        className
      )}
      {...eventHandlers}
      style={{
        cursor: isDragScrollEnabled ? (isDragging ? "grabbing" : "grab") : "default",
      }}
    >
      {innerHeader && (
        <CardHeader
          ref={cardHeaderRef}
          title={title}
          titleClassName={titleClassName}
          subtitle={subtitle}
          subtitleClassName={subtitleClassName}
          {...headerProps}
          headerTextClassName={twMerge(headerProps?.headerTextClassName, "mb-0")}
          headerClassName={twMerge(
            "pt-6 pb-4 px-6",

