export const ViewDataModal = <T extends Record<string, unknown> | Record<string, unknown>[] | null = JobDetails>({
  data = {} as T,
  title = "View Data",
}: {
  data: T;
  title?: string;
}) => {
  const [search, setSearch] = useState("");
  const debouncedSearch = useDebounce(search, 250);
  const [currentLineIdx, _setCurrentLineIdx] = useState(0);
  const [editMetadata, setEditMetadata] = useState(false);

  const { eventHandlers, isDragging, isOverflowing, isSkip } = useDragScroll<HTMLDivElement>({
    disableModifierKey: "Shift",
  });

  const [_json, stringifiedLines] = useMemo<[string, string[]]>(() => {
    try {
      const jsonString = JSON.stringify(sanitizeForJson(data), null, 2) ?? "";
      const stringifiedLines = highlightJson(jsonString).split("\n");
      return [jsonString, stringifiedLines];
    } catch (e) {
      console.warn("Failed to stringify data for MetadataModal:", e);
      // fallback if something explodes
      return [String(data), String(data).split("\n")];
    }
  }, [data]);

  const lowerLines = useMemo(() => stringifiedLines.map((line) => line.toLocaleLowerCase()), [stringifiedLines]);
  const { filteredLinesIdx } = useMemo(() => {
    if (!debouncedSearch.length) return { filteredLinesIdx: [] };
    const searchQ = debouncedSearch.toLocaleLowerCase().split(";").filter(Boolean);
    const filteredLinesIdx: number[] = [];
    for (let i = 0; i < lowerLines.length; i++) {
      if (searchQ.some((q) => lowerLines[i].includes(q))) filteredLinesIdx.push(i);
    }
    return { filteredLinesIdx };
  }, [debouncedSearch, lowerLines]);

  // The virtualizer

